function shares(part, whole) {
  // Верните { share, percent } с одним знаком после запятой.
  // share = part/whole (доля 0..1); percent = share*100.
  // whole <= 0 или некорректный ввод -> null целиком.
  // Return { share, percent } with one decimal.
  // share = part/whole (a 0..1 fraction); percent = share*100.
  // whole <= 0 or invalid input -> null outright.
}

practice.solution:
function shares(part, whole) {
  const inputs = [part, whole];
  if (!inputs.every(n => typeof n === 'number' && Number.isFinite(n) && n >= 0)) return null;
  if (!(whole > 0)) return null;
  const share = Math.round(part / whole * 1000) / 1000;
  return { share, percent: Math.round(part / whole * 1000) / 10 };
}

