function centralMeasures(values) {
  // Верните { mean, median, mode } с одним знаком после запятой.
  // Пустой массив или нечисловые значения -> null.
  // Мода: значение с максимальной частотой; ничья — наименьшее; без повторов — null.
  // Return { mean, median, mode } with one decimal.
  // An empty array or non-numeric values -> null.
  // Mode: the value with the highest frequency; ties -> smallest; no repeats -> null.
}

practice.solution:
function centralMeasures(values) {
  if (!Array.isArray(values) || values.length === 0) return null;
  if (!values.every(n => typeof n === 'number' && Number.isFinite(n))) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const mean = Math.round(values.reduce((s, n) => s + n, 0) / values.length * 10) / 10;
  const mid = Math.floor(sorted.length / 2);
  const median = sorted.length % 2 ? sorted[mid] : Math.round((sorted[mid - 1] + sorted[mid]) / 2 * 10) / 10;
  const freq = new Map();
  for (const n of sorted) freq.set(n, (freq.get(n) || 0) + 1);
  let mode = null, best = 1;
  for (const [n, c] of freq) if (c > best || (c === best && mode !== null && n < mode)) { mode = n; best = c; }
  if (best === 1) mode = null;
  return { mean, median, mode };
}

