function spread(values) {
  // Верните { range, q1, q3, iqr } с одним знаком после запятой.
  // Метод половин: нижняя половина до медианы, верхняя после.
  // Пустой массив или нечисловые значения -> null.
  // Return { range, q1, q3, iqr } with one decimal.
  // Halves method: the lower half before the median, the upper after.
  // An empty array or non-numerics -> null.
}

practice.solution:
function spread(values) {
  if (!Array.isArray(values) || values.length === 0) return null;
  if (!values.every(n => typeof n === 'number' && Number.isFinite(n))) return null;
  const sorted = [...values].sort((a, b) => a - b);
  const r = (n) => Math.round(n * 10) / 10;
  const range = r(sorted[sorted.length - 1] - sorted[0]);
  const medianIndex = Math.floor(sorted.length / 2);
  const lower = sorted.slice(0, medianIndex), upper = sorted.slice(sorted.length % 2 ? medianIndex + 1 : medianIndex);
  const med = (arr) => arr.length ? (arr.length % 2 ? arr[Math.floor(arr.length / 2)] : (arr[arr.length / 2 - 1] + arr[arr.length / 2]) / 2) : sorted[medianIndex];
  const q1 = r(med(lower)), q3 = r(med(upper));
  return { range, q1, q3, iqr: r(q3 - q1) };
}

