function kpiMetrics(rows) {
  // Верните { revenue, avgPurchaseCheck, returnSharePercent }.
  // revenue — сумма всех числовых total (возвраты входят со знаком).
  // avgPurchaseCheck — среднее положительных total, один знак после запятой; нет покупок -> null.
  // returnSharePercent — |сумма возвратов| / revenue в процентах, один знак; выручка 0 -> null.
  // NULL и нечисловые total пропускаются; пустой список или не-массив -> null.
}

practice.solution:
function kpiMetrics(rows) {
  if (!Array.isArray(rows)) return null;
  let revenue = 0, purchaseSum = 0, purchases = 0, returnSum = 0;
  for (const row of rows) {
    const t = row && typeof row.total === 'number' && Number.isFinite(row.total) ? row.total : null;
    if (t === null) continue;
    revenue += t;
    if (t > 0) { purchases += 1; purchaseSum += t; }
    if (t < 0) returnSum += -t;
  }
  if (rows.length === 0) return null;
  return {
    revenue,
    avgPurchaseCheck: purchases ? Math.round(purchaseSum / purchases * 10) / 10 : null,
    returnSharePercent: revenue !== 0 ? Math.round(returnSum / Math.abs(revenue) * 1000) / 10 : null
  };
}

demo.code:
const rows = [{ total: 90 }, { total: -90 }, { total: null }];
kpiMetrics(rows);
// revenue: 90 + (-90) = 0
// purchases: 1, purchaseSum: 90
// returnSum: 90
// revenue === 0 -> returnSharePercent: null

