function cohortRetention(cohorts) {
  // Верните массив { id, rates } — rates[i] = active[i] / size в процентах,
  // округлённых до целого числа.
  // Не-массив или пустой список -> null; некорректная когорта -> null.
}

practice.solution:
function cohortRetention(cohorts) {
  if (!Array.isArray(cohorts) || cohorts.length === 0) return null;
  const out = [];
  for (const c of cohorts) {
    if (!c || typeof c.size !== 'number' || !(c.size > 0) || !Array.isArray(c.active)) return null;
    const rates = c.active.map(a => Math.round(a / c.size * 100));
    out.push({ id: c.id, rates });
  }
  return out;
}
